cd /workspace && python -c "
from snake import new_game, step, snapshot
SCHEDULE = {5:'down', 9:'left', 14:'up', 20:'right'}
st = new_game()
for t in range(1, 61):
    step(st, SCHEDULE.get(t))
    s = snapshot(st)
    if t <= 30 or not s['alive']:
        print(t, 'head', s['snake'][0], 'dir', s['dir'], 'score', s['score'], 'len', len(s['snake']), 'alive', s['alive'], ('death_tick='+str(s['death_tick'])) if not s['alive'] else '')
    if not s['alive']:
        break
"
